module div_8bit(
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    input res_ready,
    output reg res_valid,
    output reg [15:0] result
);
    // Input registers to store the input operands
    reg [7:0] dividend_reg;
    reg [7:0] divisor_reg;

    // Output registers to store the quotient and remainder
    reg [7:0] quotient;
    reg [7:0] remainder;

    // Control signals
    reg [3:0] count;
    reg start;
    reg [8:0] divisor_extend;
    reg [8:0] neg_divisor;
    reg [9:0] all_sub_result;
    reg [8:0] sub_result;
    reg [8:0] sub_remainder_reg_divisor;
    reg [7:0] remainer;
    reg [7:0] quotient_reg;
    reg carry_out;
    reg [8:0] mux_result;
    reg [7:0] quotient_shift;
    reg [15:0] sr_final_update;
    reg [15:0] sr_shifting;
    reg [7:0] dividend_abs;
    reg [7:0] final_remainer;
    reg [7:0] final_quotient;
    reg is_final_quotient_sign;

    // Divisor extension logic
    always @(*) begin
        if (sign && divisor[7]) begin
            divisor_extend = {1'b1, divisor};
        end else begin
            divisor_extend = {1'b0, divisor};
        end
    end

    // Negative divisor logic
    always @(*) begin
        if (sign && divisor[7]) begin
            neg_divisor = -divisor_extend;
        end else begin
            neg_divisor = divisor_extend;
        end
    end

    // Subtraction result logic
    always @(*) begin
        all_sub_result = {remainer, quotient_reg[7:0]} + neg_divisor;
    end

    // Subtraction result logic
    always @(*) begin
        sub_result = all_sub_result[8:0];
    end

    // Remainder and quotient register logic
    always @(posedge clk) begin
        if (rst) begin
            sub_remainder_reg_divisor <= 0;
        end else begin
            sub_remainder_reg_divisor <= {all_sub_result[7:0], divisor_extend[8]};
        end
    end

    // Remainder logic
    always @(*) begin
        remainer = sub_remainder_reg_divisor[8:1];
    end

    // Quotient logic
    always @(*) begin
        quotient_reg = {quotient_reg[6:0], all_sub_result[9]};
    end

    // Carry out logic
    always @(*) begin
        carry_out = all_sub_result[9];
    end

    // Multiplexer result logic
    always @(*) begin
        if (carry_out) begin
            mux_result = sub_result;
        end else begin
            mux_result = {1'b0, remainer};
        end
    end

    // Quotient shift logic
    always @(*) begin
        quotient_shift = {quotient_reg[7:1], carry_out};
    end

    // Shift register final update logic
    always @(posedge clk) begin
        if (rst) begin
            sr_final_update <= 0;
        end else begin
            sr_final_update <= {mux_result, quotient_shift[7:0], carry_out, 1'b0};
        end
    end

    // Shift register shifting logic
    always @(*) begin
        sr_shifting = {sr_final_update[14:0], 1'b0};
    end

    // Dividend absolute value logic
    always @(*) begin
        if (sign && dividend[7]) begin
            dividend_abs = -dividend;
        end else begin
            dividend_abs = dividend;
        end
    end

    // Final remainder logic
    always @(*) begin
        if (sign && dividend[7]) begin
            final_remainer = -remainer;
        end else begin
            final_remainer = remainer;
        end
    end

    // Final quotient logic
    always @(*) begin
        if (sign && (divisor[7] ^ dividend[7])) begin
            final_quotient = -quotient_reg;
        end else begin
            final_quotient = quotient_reg;
        end
    end

    // Sign of final quotient logic
    always @(*) begin
        is_final_quotient_sign = sign && (divisor[7] ^ dividend[7]);
    end

    // Result logic
    always @(*) begin
        result = {final_remainer, final_quotient};
    end

    // Reset result_valid on reset
    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
        end
    end

    // Set res_valid when the result is ready
    always @(posedge clk) begin
        if (opn_valid && !res_ready) begin
            res_valid <= 1;
        end else if (res_valid && res_ready) begin
            res_valid <= 0;
        end
    end

    // Counter logic
    always @(posedge clk) begin
        if (rst) begin
            count <= 0;
            start <= 0;
        end else if (opn_valid && !res_ready) begin
            count <= 1;
            start <= 1;
        end else if (count == 8) begin
            count <= 0;
            start <= 0;
        end else if (res_ready) begin
            count <= count + 1;
        end
    end

endmodule
